{{ config(materialized='table') }}
-- Self-referencing table(s): 'WI_AUD_RSTD_BKGS_MEASURE_MTH' used as both source and target in this mapping.
-- Materialized as TABLE to snapshot source data before the target model overwrites it.
SELECT
'MT_RSTD_BKGS_MEASURE_ORDER_MTH' AS AUDIT_TABLE_NAME,
COALESCE(RST.DV_FISCAL_YEAR_MTH_NUMBER_INT,ACT.DV_FISCAL_YEAR_MTH_NUMBER_INT) AS DV_FISCAL_YEAR_MTH_NUMBER_INT,
NULL AS FISCAL_YEAR_QUARTER_NUMBER_INT,
COALESCE(RST.BKGS_MEASURE_TRANS_TYPE_CODE,ACT.BKGS_MEASURE_TRANS_TYPE_CODE) AS BKGS_MEASURE_TRANS_TYPE_CODE,
ZEROIFNULL(RST.TRADE_IN_AMOUNT )- ZEROIFNULL(ACT.TRADE_IN_AMOUNT) AS TRADE_IN_AMOUNT,
ZEROIFNULL(RST.DD_COMP_US_NET_PRICE_AMOUNT )- ZEROIFNULL(ACT.DD_COMP_US_NET_PRICE_AMOUNT) AS DD_COMP_US_NET_PRICE_AMOUNT,
ZEROIFNULL(RST.DD_COMP_US_LIST_PRICE_AMOUNT )- ZEROIFNULL(ACT.DD_COMP_US_LIST_PRICE_AMOUNT ) AS DD_COMP_US_LIST_PRICE_AMOUNT,
ZEROIFNULL(RST.DD_COMP_US_COST_AMOUNT)- ZEROIFNULL(ACT.DD_COMP_US_COST_AMOUNT ) AS DD_COMP_US_COST_AMOUNT,
ZEROIFNULL(RST.DD_EXTENDED_QUANTITY)- ZEROIFNULL(ACT.DD_EXTENDED_QUANTITY ) AS DD_EXTENDED_QUANTITY,
ZEROIFNULL(RST.DD_COMP_US_HOLD_NET_PRICE_AMT)- ZEROIFNULL(ACT.DD_COMP_US_HOLD_NET_PRICE_AMT ) AS DD_COMP_US_HOLD_NET_PRICE_AMT,
ZEROIFNULL(RST.DD_COMP_US_HOLD_LIST_PRICE_AMT)- ZEROIFNULL(ACT.DD_COMP_US_HOLD_LIST_PRICE_AMT ) AS DD_COMP_US_HOLD_LIST_PRICE_AMT,
ZEROIFNULL(RST.DD_COMP_US_HOLD_COST_AMOUNT)- ZEROIFNULL(ACT.DD_COMP_US_HOLD_COST_AMOUNT ) AS DD_COMP_US_HOLD_COST_AMOUNT,
ZEROIFNULL(RST.DD_EXTENDED_HOLD_QUANTITY )- ZEROIFNULL(ACT.DD_EXTENDED_HOLD_QUANTITY ) AS DD_EXTENDED_HOLD_QUANTITY,
ZEROIFNULL(RST.DD_COMP_US_STANDARD_PRICE_AMT)- ZEROIFNULL(ACT.DD_COMP_US_STANDARD_PRICE_AMT) AS DD_COMP_US_STANDARD_PRICE_AMT,
CURRENT_USER AS EDW_CREATE_USER,
CURRENT_USER AS EDW_UPDATE_USER,
CURRENT_TIMESTAMP(0) AS EDW_CREATE_DATETIME,
CURRENT_TIMESTAMP(0) AS EDW_UPDATE_DATETIME
FROM
(
SELECT
NBM.FISCAL_YEAR_MONTH_INT AS DV_FISCAL_YEAR_MTH_NUMBER_INT,
BKGS_MEASURE_TRANS_TYPE_CD AS BKGS_MEASURE_TRANS_TYPE_CODE,
SUM(ZEROIFNULL(TRADE_IN_AMT))  TRADE_IN_AMOUNT,
SUM(ZEROIFNULL(COMP_US_NET_PRICE_AMT)) DD_COMP_US_NET_PRICE_AMOUNT,
SUM(ZEROIFNULL(COMP_US_LIST_PRICE_AMT)) DD_COMP_US_LIST_PRICE_AMOUNT,
SUM(ZEROIFNULL(COMP_US_COST_AMT)) DD_COMP_US_COST_AMOUNT,
SUM(ZEROIFNULL(EXTENDED_QTY)) DD_EXTENDED_QUANTITY,
SUM(ZEROIFNULL(COMP_US_HOLD_NET_PRICE_AMT))  DD_COMP_US_HOLD_NET_PRICE_AMT,
SUM(ZEROIFNULL(COMP_US_HOLD_LIST_PRICE_AMT))  DD_COMP_US_HOLD_LIST_PRICE_AMT,
SUM(ZEROIFNULL(COMP_US_HOLD_COST_AMT)) DD_COMP_US_HOLD_COST_AMOUNT,
SUM(ZEROIFNULL(EXTENDED_HOLD_QTY)     ) DD_EXTENDED_HOLD_QUANTITY,
SUM(ZEROIFNULL(COMP_US_STANDARD_PRICE_AMT )) DD_COMP_US_STANDARD_PRICE_AMT
FROM
{{ source('raw', 'MT_BKGS_MEASURE_ORDER_MTH') }} NBM
INNER JOIN
{{ source('raw', 'R_FISCAL_MONTH_TO_YEAR') }} RFM
ON (
(COLLATE( RFM.PREVIOUS_FSCL_MONTH_FLAG, 'en-ci-rtrim') = 'Y'  AND CURRENT_DATE() BETWEEN RFM.FISCAL_MONTH_END_DATE + 1 AND  RFM.FISCAL_MONTH_END_DATE + 6)
OR COLLATE( RFM.CURRENT_FISCAL_MONTH_FLAG, 'en-ci-rtrim') = 'Y'
)
WHERE RFM.FISCAL_YEAR_MONTH_INT = NBM.FISCAL_YEAR_MONTH_INT
GROUP BY 1,2) ACT

FULL OUTER JOIN
(
SELECT
NBM.FISCAL_YEAR_MONTH_INT AS DV_FISCAL_YEAR_MTH_NUMBER_INT,
BKGS_MEASURE_TRANS_TYPE_CD AS BKGS_MEASURE_TRANS_TYPE_CODE,
SUM(ZEROIFNULL(TRADE_IN_AMT))  TRADE_IN_AMOUNT,
SUM(ZEROIFNULL(COMP_US_NET_PRICE_AMT)) DD_COMP_US_NET_PRICE_AMOUNT,
SUM(ZEROIFNULL(COMP_US_LIST_PRICE_AMT)) DD_COMP_US_LIST_PRICE_AMOUNT,
SUM(ZEROIFNULL(COMP_US_COST_AMT)) DD_COMP_US_COST_AMOUNT,
SUM(ZEROIFNULL(EXTENDED_QTY)) DD_EXTENDED_QUANTITY,
SUM(ZEROIFNULL(COMP_US_HOLD_NET_PRICE_AMT))  DD_COMP_US_HOLD_NET_PRICE_AMT,
SUM(ZEROIFNULL(COMP_US_HOLD_LIST_PRICE_AMT))  DD_COMP_US_HOLD_LIST_PRICE_AMT,
SUM(ZEROIFNULL(COMP_US_HOLD_COST_AMT)) DD_COMP_US_HOLD_COST_AMOUNT,
SUM(ZEROIFNULL(EXTENDED_HOLD_QTY)     ) DD_EXTENDED_HOLD_QUANTITY,
SUM(ZEROIFNULL(COMP_US_STANDARD_PRICE_AMT )) DD_COMP_US_STANDARD_PRICE_AMT
FROM
{{ source('raw', 'MT_RSTD_BKGS_MEASURE_ORDER_MTH') }} NBM
INNER JOIN
{{ source('raw', 'R_FISCAL_MONTH_TO_YEAR') }} RFM
ON (
(COLLATE( RFM.PREVIOUS_FSCL_MONTH_FLAG, 'en-ci-rtrim') = 'Y'  AND CURRENT_DATE() BETWEEN RFM.FISCAL_MONTH_END_DATE + 1 AND  RFM.FISCAL_MONTH_END_DATE + 6)
OR COLLATE( RFM.CURRENT_FISCAL_MONTH_FLAG, 'en-ci-rtrim') = 'Y'
)
WHERE RFM.FISCAL_YEAR_MONTH_INT = NBM.FISCAL_YEAR_MONTH_INT
GROUP BY 1,2) RST
ON
ACT.DV_FISCAL_YEAR_MTH_NUMBER_INT = RST.DV_FISCAL_YEAR_MTH_NUMBER_INT
AND ACT.BKGS_MEASURE_TRANS_TYPE_CODE = RST.BKGS_MEASURE_TRANS_TYPE_CODE